import { AxisScale } from '@visx/axis';
import { GridProps as VisxGridProps } from '@visx/grid/lib/grids/Grid';
import { Group } from '@visx/group';
import React from 'react';

import { GridColumns } from '../../../core/components/grid/GridColumns.js';
import { GridRows } from '../../../core/components/grid/GridRows.js';
import {
  getVerticalNumTicks,
  getHorizontalNumTicks,
} from '../../../core/functions/ticks.js';

export type GridProps = VisxGridProps<AxisScale<number>, AxisScale<number>>;

/**
 * The grid columns component for charts
 */
export function Grid({ width, height, xScale, yScale }: GridProps) {
  const numTicksRows = getVerticalNumTicks(height);
  const autoNumTicks = getHorizontalNumTicks(width);

  return (
    <Group data-testid="histogram-chart-grid-lines">
      <GridColumns
        data-testid="chart-grid-columns"
        width={width}
        height={height}
        scale={xScale}
        numTicks={autoNumTicks}
        highlightZeroLine={false}
      />
      <GridRows
        data-testid="chart-grid-rows"
        width={width}
        height={height}
        scale={yScale}
        numTicks={numTicksRows}
      />
    </Group>
  );
}
